=== VarStatModType
     1	public enum VarStatModType
     2	{
     3		Override = 0,
     4		OverrideWithMods = 1,
     5		Multiplicative = 2,
     6		Additive = 3,
     7		LateMultiplicative = 4,
     8		Custom = 8
