=== NumVarStat
     1	using System;
     2	using System.Linq;
     3	
     4	[Serializable]
     5	public class NumVarStat : VarStat<float>
     6	{
     7		public bool syncCurrentToModMax;
     8	
     9		public float minMaxVal;
    10	
    11		public override float CurrentValue
    12		{
    13			get
    14			{
    15				return (!syncCurrentToModMax) ? _currentValue : ModifiedValue;
    16			}
    17			set
    18			{
    19				_currentValue = ((!syncCurrentToModMax && !(value > ModifiedValue)) ? value : ModifiedValue);
    20				if (_currentValue < 0f)
    21				{
    22					_currentValue = 0f;
    23				}
    24				AnnounceStatChangedEvent();
    25			}
    26		}
    27	
    28		public override float BaseValue
    29		{
    30			get
    31			{
    32				return _baseValue;
    33			}
    34			set
    35			{
    36				_baseValue = ((!(value > minMaxVal)) ? minMaxVal : value);
    37			}
    38		}
    39	
    40		public override float ModifiedValue
    41		{
    42			get
    43			{
    44				return _modifiedValue;
    45			}
    46			set
    47			{
    48				_modifiedValue = ((!(value > minMaxVal)) ? minMaxVal : value);
    49			}
    50		}
    51	
    52		public NumVarStat(float newBaseVal, bool syncCurrentToModMax = false)
    53			: base(newBaseVal)
    54		{
    55			CurrentValue = newBaseVal;
    56			this.syncCurrentToModMax = syncCurrentToModMax;
    57		}
    58	
    59		public NumVarStat(int newBaseVal)
    60			: this(newBaseVal, false)
    61		{
    62		}
    63	
    64		public override void Reprioritize()
    65		{
    66			modifiers = (from x in modifiers
    67				orderby x.modType, ((NumVarStatMod)x).priority, ((NumVarStatMod)x).modValue descending
    68				select x).ToList();
    69		}
    70	}
=== NumVarStatMod
     1	public class NumVarStatMod : VarStatMod<float>
     2	{
     3		public float modValue;
     4	
     5		public bool fillToNewMax;
     6	
     7		public NumVarStatMod(string newID, float newModValue, int newPriority = 10, VarStatModType modType = VarStatModType.Additive, bool fillToNewMax = false)
     8			: base(newID, newPriority, modType)
     9		{
    10			modValue = newModValue;
    11			base.modType = modType;
    12			this.fillToNewMax = fillToNewMax;
    13		}
    14	
    15		public void ApplyMultiplicative(VarStat<float> varStatToMod)
    16		{
    17			varStatToMod.ModifiedValue += varStatToMod.ModifiedValue * (1f + modValue) - varStatToMod.ModifiedValue;
    18		}
    19	
    20		public override void Apply(VarStat<float> varStatToMod)
    21		{
    22			base.Apply(varStatToMod);
    23			if (modType == VarStatModType.Override || modType == VarStatModType.OverrideWithMods)
    24			{
    25				varStatToMod.ModifiedValue = modValue;
    26			}
    27			else
    28			{
    29				switch (modType)
    30				{
    31				case VarStatModType.Additive:
    32					varStatToMod.ModifiedValue += modValue;
    33					break;
    34				case VarStatModType.Multiplicative:
