	{
		if (!GameDataManager.GameCleared || Level.isBossRushMode)
		{
			gameObject.SetActive(value: false);
		}
		else
		{
			base.Start();
		}
	}

	public override bool HandleConditionalInteraction()
	{
		switch (CurrentDialogIndex)
		{
		case 3:
			if (Player.platWallet.balance < platCost)
			{
				CurrentDialogIndex = 4;
			}
			break;
		case 4:
			CurrentDialogIndex = 5;
			Player.platWallet.Withdraw(platCost);
			SoundManager.PlayAudio("MenuBuy");
			SoundManager.PlayAudio("Looper0");
			loopReady = true;
			PlayDefaultEmote();
			GameController.PauseAllPlayers();
			break;
		case 5:
			playerLeavingDialog = true;
			return true;
		}
		return false;
	}

	public override void Exiting()
	{
		if (loopReady)
		{
			player = null;
			GameUI.dialogManager.ResetDialog(myDialogID);
			GameUI.dialogManager.Deactivate();
			activationTrigger.enabled = false;
			loopReady = false;
			loopStarted = true;
			StartCoroutine(InitiateLoop());
		}
		else if (!loopStarted)
		{
			base.Exiting();
		}
	}

	private IEnumerator InitiateLoop()
	{
		anim.Play("Rest", -1, 0f);
		yield return null;
		while (!anim.AnimPlayed())
		{
			yield return null;
		}
		sparkleEmitter = PoolManager.GetPoolItem<ParticleEffect>("SparkleEffect");
		sparkleEmitter.followTransform = hourglassTrans;
		sparkleEmitter.reqFollowTrans = true;
		sparkleEmitter.Play(8f, hourglassTrans.position, null, 0.5f);
		yield return null;
		anim.Play("Hourglass", -1, 0f);
		yield return null;
		Vector3 camLocation = GameController.cameraController.transform.position;
		camLocation.y = transform.position.y + 3f;
		CameraController cameraController = GameController.cameraController;
		Vector3? targetLoc = camLocation;
		cameraController.OverrideAndMoveCameraToLocation(null, targetLoc, 1f, followPlayer: false, setLocks: true, vertLockStatus: true, horiLockStatus: true);
		while (!anim.AnimPlayed())
		{
			yield return null;
		}
		if (sparkleEmitter != null)
		{
			sparkleEmitter.Stop();
		}
		SoundManager.PlayAudio("CrestSpinUp");
		yield return Globals.waitForQuarter;
		anim.Play("HourglassSpin", -1, 0f);
		yield return Globals.waitForOne;
		CameraController.ShakeCamera();
		SoundManager.PlayAudio("LightFillScreen");
		GameController.overlayEffects.imageTrans.pivot = Camera.main.WorldToViewportPoint(hourglassTrans.position);
		GameController.overlayEffects.imageTrans.anchoredPosition = Vector3.zero;
		GameController.overlayEffects.anim.Play("HoriWhiteFill", -1, 0f);
		yield return null;
		while (!GameController.overlayEffects.anim.AnimPlayed(1.25f))
		{
			GameController.overlayEffects.imageTrans.pivot = Camera.main.WorldToViewportPoint(hourglassTrans.position);
			yield return null;
		}
		GameController.overlayEffects.anim.Play("WhiteToBlack", -1, 0f);
		yield return Globals.waitForOne;
		LoadLoop();
	}

	public void LoadLoop()
	{
		EnemyGlobalStatManager.useDiffScaling = true;
		GameController.loopCount++;
		GameController.stageCount = 0;
		GameController.tierCount = 0;
		GameController.NextLevelName = string.Empty;
		GameController.LoadLevel(NextLevelLoader.GetCurrentTierScene());
		Level.resetUsedRooms = true;
	}
}
