				yield return waitForShotDelay;
			}
			while (fsm.currentStateName.Contains("Shoot"))
			{
				yield return null;
			}
			inputVector = Vector3.zero;
			yield return Globals.waitForOne;
			StartCoroutine(MoveToPosition(startPosition));
			while (movingToPosition)
			{
				yield return null;
			}
			StartCoroutine(MoveToPosition(startPositionOffset));
			while (movingToPosition)
			{
				yield return null;
			}
			yield return Globals.waitForOne;
		}
	}

	public IEnumerator MoveToPosition(Vector3 targetVec)
	{
		if (!movingToPosition)
		{
			movingToPosition = true;
			targetVector = targetVec;
			fsm.ChangeState("RunToTarget");
			yield return null;
			while (fsm.currentStateName.Contains("Run"))
			{
				yield return null;
			}
			movingToPosition = false;
		}
	}

	public IEnumerator DashPracticeLoop()
	{
		int dashCounter = 4;
		bool flipDirection = false;
		WaitForSeconds dashDelay = new WaitForSeconds(0.375f);
		WaitForSeconds cycleDelay = new WaitForSeconds(1.25f);
		while (true)
		{
			flipDirection = !flipDirection;
			Vector3 calcDashVector = (((!flipDirection) ? Vector3.left : Vector3.right) + Vector3.up * 0.25f).normalized;
			yield return StartCoroutine(MoveToPosition(transform.position + calcDashVector * 0.5f));
			movement.moveVector = calcDashVector;
			movement.dashVector = calcDashVector;
			fsm.ChangeState("Dash", allowSelfTransition: true);
			yield return dashDelay;
			dashCounter--;
			if (dashCounter <= 0)
			{
				calcDashVector = Vector2.down;
				yield return StartCoroutine(MoveToPosition(transform.position + calcDashVector * 0.5f));
				movement.moveVector = calcDashVector;
				movement.dashVector = calcDashVector;
				fsm.ChangeState("Dash", allowSelfTransition: true);
				yield return dashDelay;
				yield return cycleDelay;
				yield return StartCoroutine(MoveToPosition(myOrigin));
				dashCounter = 4;
			}
			yield return null;
		}
	}
}
using System.Collections.Generic;
using Chaos.ListExtensions;
using UnityEngine;

public class BroomNpc : Npc
{
	public class BroomIdleState : State<BroomNpc>
	{
		private int broomIdleStopwatchID = -1;

		private new BroomNpc parent;

		public BroomIdleState(string stateName, FSM parentFSM, BroomNpc parentObj)
			: base(stateName, parentFSM, parentObj)
		{
			parent = parentObj;
		}

		public override void OnEnter()
		{
			broomIdleStopwatchID = ChaosStopwatch.Begin(Random.Range(1f, 3f));
			parent.anim.Play("Idle", -1, 0f);
		}

		public override void Update()
		{
			if (!(parent.player != null) && ChaosStopwatch.Check(broomIdleStopwatchID))
			{
				fsm.ChangeState("Roam");
			}
		}
	}

	public class BroomRoamState(string stateName, FSM parentFSM, BroomNpc parentEntity) : State<BroomNpc>(stateName, parentFSM, parentEntity)
	{
		private ParticleEffect musicNoteEmitter;

		private int broomRoamStopwatchID = -1;

		private Vector2 moveVector = Vector2.zero;

		private float animSpeed = 1f;

		private List<Vector3> validVectors;

		public override void OnEnter()
		{
			parent.CurrentOverheadPrompt = null;
			moveVector = Vector2.zero;
			if (parent.sweepDirOverride == Vector2.zero)
			{
				if (validVectors == null)
				{
					validVectors = new List<Vector3>();
				}
				validVectors.Clear();
				for (float num = 4f; num > 0f; num -= 0.25f)
				{
					for (int i = 0; i < 16; i++)
					{
						Vector3 vector = Globals.GetCirclePositionVector(16, i);
						if (!Entity.IsPathObstructed(parent.transform.position, vector, num, parent.collisionLayerMask))
						{
							validVectors.Add(vector);
						}
					}
					if (validVectors.Count > 0)
					{
						break;
					}
				}
				if (validVectors.Count > 0)
				{
					moveVector = validVectors.GetRandomValue();
				}
			}
			else
			{
				moveVector = parent.sweepDirOverride;
			}
			if (moveVector != Vector2.zero)
			{
				animSpeed = Random.Range(1f, 3f);
				parent.anim.speed = animSpeed;
				parent.anim.Play("Sweep", -1, 0f);
				parent.movement.moveSpeedStat.CurrentValue = Random.Range(2f, 5f);
				parent.movement.moveVector = moveVector;
				broomRoamStopwatchID = ChaosStopwatch.Begin(Random.Range(2.5f, 4f));
				musicNoteEmitter = PoolManager.GetPoolItem<ParticleEffect>("MusicNoteEmitter");
				musicNoteEmitter.followOffset = new Vector3(0f, 1.5f, 0f);
				ParticleEffect particleEffect = musicNoteEmitter;
				float? emissionRate = 4f;
				Vector3? position = parent.transform.position;
				Transform transform = parent.transform;
				particleEffect.Play(emissionRate, position, null, null, transform);
			}
			else
			{
				fsm.ChangeState("Idle");
			}
		}

		public override void Update()
		{
			if (ChaosStopwatch.Check(broomRoamStopwatchID))
			{
				fsm.ChangeState("Idle");
			}
		}

		public override void FixedUpdate()
		{
			if (!Entity.IsPathObstructed(parent.transform.position, moveVector, 1f, parent.collisionLayerMask))
			{
				parent.movement.MoveToMoveVector();
			}
			else
			{
				fsm.ChangeState("Idle");
			}
		}

		public override void OnExit()
		{
			parent.movement.EndMovement();
			parent.anim.speed = 1f;
			if (musicNoteEmitter != null)
			{
				musicNoteEmitter.Stop();
				musicNoteEmitter = null;
			}
		}
	}

	public class BroomSpeakingState : State<BroomNpc>
	{
		public BroomSpeakingState(string stateName, FSM parentFSM, BroomNpc parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}
	}

	public FSM fsm;

	public Vector2 sweepDirOverride;

	[HideInInspector]
	private int collisionLayerMask;

	[HideInInspector]
	public Movement movement;

	public string currentStateName;

	public void EmitDust(float left)
	{
		Vector3 vector = Vector3.left;
		if (left != 1f)
		{
			vector = Vector3.right;
		}
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 5;
		float z = Globals.GetRotationVector(vector).z;
		float startSpeed = 1.5f;
		Vector3? emitPosition = transform.position + vector * 0.5f;
		poolItem.EmitDirBurst(particleCount, z, startSpeed, -1f, -1f, emitPosition);
	}

	public override void Awake()
	{
		base.Awake();
		InitComponents();
		InitFSM();
	}

	public override void Start()
	{
		base.Start();
		collisionLayerMask = ChaosCollisions.layerAll | ChaosCollisions.layerDestructible | ChaosCollisions.layerAllyFloor;
	}

	public override void Update()
	{
		base.Update();
		if (fsm != null)
		{
			if (!fsm.AnyStateUpdate())
			{
				fsm.currentState.Update();
			}
			currentStateName = fsm.currentState.name;
		}
	}

	public void FixedUpdate()
	{
		if (fsm != null)
		{
			fsm.currentState.FixedUpdate();
		}
	}

	public virtual void InitComponents()
	{
		movement = GetComponent<Movement>();
	}

	public virtual void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new BroomIdleState("Idle", fsm, this));
		fsm.AddState(new BroomRoamState("Roam", fsm, this));
		fsm.AddState(new BroomSpeakingState("Speaking", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}

	public override void OnTriggerStay2D(Collider2D col)
	{
	}
}

using System.Collections;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class MuseumSignatureExample : MonoBehaviour
{
	public float repeatTime = 5f;

	private ChaosQuickStopwatch repeatStopwatch = new ChaosQuickStopwatch(5f);

	private Animator anim;

	private SpriteRenderer spriteRenderer;

	public Transform spawnTransform;

	private OverdriveEffects overdriveEffects;

	private Animator[] ghoulAnims = new Animator[3];

	private Material[] ghoulMats = new Material[3];

	private Vector2 leftVector = new Vector2(-1f, -1f);

	private Vector2 rightVector = new Vector2(1f, -1f);

	private bool isRight;

	private Vector2 startVector;

	private Vector2 endVector;

	private ChaosQuickStopwatch ultStopwatch = new ChaosQuickStopwatch(2f);

	private float ultLerpValue;

	private ChaosQuickStopwatch ghoulStopwatch = new ChaosQuickStopwatch();

	private FireBlast currentFB;

	private WaitForSeconds waitForFlash = new WaitForSeconds(0.03f);

	private WaitForSeconds waitForOneSecond = new WaitForSeconds(1f);

	private bool ghoulsDead;

	private AudioSource odLoopAudio;

	private void Awake()
	{
		anim = GetComponent<Animator>();
		spriteRenderer = base.transform.Find("PlayerSprite").GetComponent<SpriteRenderer>();
		spriteRenderer.material = new Material(spriteRenderer.material);
		spriteRenderer.material.SetFloat("_PaletteIndex", 15f);
		for (int i = 0; i < 3; i++)
		{
			Transform transform = base.transform.parent.Find("Ghoul" + i);
			ghoulAnims[i] = transform.GetComponent<Animator>();
			ghoulMats[i] = transform.Find("EnemySprite").GetComponent<SpriteRenderer>().material;
		}
	}

	private void Start()
	{
		overdriveEffects = Globals.ChaosInst<OverdriveEffects>(OverdriveEffects.Prefab, transform);
		overdriveEffects.SetFollowTransform(transform);
		repeatStopwatch.SetDelay(repeatTime);
		if (spawnTransform == null)
		{
			spawnTransform = transform;
		}
	}

	private void Update()
	{
		if (!repeatStopwatch.IsRunning)
		{
			repeatStopwatch.IsRunning = true;
			StartCoroutine(HandleFireBlast());
		}
	}

	private IEnumerator HandleFireBlast()
	{
		anim.Play("RunDown");
		for (int i = 0; i < 3; i++)
		{
			ghoulAnims[i].Play("IdleDown");
			ghoulMats[i].SetFloat("_FlashAmount", 1f);
		}
		yield return waitForFlash;
		float fadeInTime = 0.25f;
		while (fadeInTime > 0f)
		{
			fadeInTime -= Time.deltaTime;
			for (int j = 0; j < 3; j++)
			{
				ghoulMats[j].SetFloat("_FlashAmount", Mathf.Lerp(0f, 1f, fadeInTime * 4f));
			}
			yield return null;
		}
		for (int k = 0; k < 3; k++)
		{
			ghoulAnims[k].Play("RunRight");
			ghoulMats[k].SetFloat("_FlashAmount", 0f);
		}
		yield return waitForOneSecond;
		anim.Play("PBAoEDown", -1, 0f);
		while (!anim.AnimPlayed(0.3f))
		{
			yield return null;
		}
		overdriveEffects.Burst(80, local: true, activation: true, shakeCamera: false);
		isRight = !isRight;
		if (isRight)
		{
			startVector = rightVector;
			endVector = leftVector;
		}
		else
		{
			startVector = leftVector;
			endVector = rightVector;
		}
		currentFB = Globals.ChaosInst<FireBlast>(FireBlast.Prefab, spawnTransform, spawnTransform.position, Globals.GetRotationQuaternion(startVector));
		currentFB.CircleBlast();
		ultStopwatch.IsRunning = true;
		ghoulStopwatch.IsRunning = true;
		ghoulsDead = false;
		while (ultStopwatch.IsRunning)
		{
			ultLerpValue = ultStopwatch.TimePercentage * 2f;
			if (currentFB != null)
			{
				if (ultLerpValue <= 1f)
				{
					currentFB.transform.localEulerAngles = Globals.GetRotationVector(Vector2.Lerp(startVector, endVector, ultLerpValue));
				}
				else
				{
					currentFB.transform.localEulerAngles = Globals.GetRotationVector(Vector2.Lerp(endVector, startVector, ultLerpValue - 1f));
				}
			}
			if (!ghoulsDead && !ghoulStopwatch.IsRunning)
			{
				ghoulsDead = true;
				for (int l = 0; l < 3; l++)
				{
					ghoulAnims[l].Play("Dead");
				}
			}
			anim.Play("PBAoEDown", -1, 0.8f);
			PlayAudio();
			yield return null;
		}
		if (currentFB != null)
		{
			currentFB.EndAllAttacks();
		}
		StopAudio();
		while (!anim.AnimPlayed())
		{
			yield return null;
		}
		anim.Play("RunDown");
	}

	private void PlayAudio()
	{
		if (odLoopAudio == null || !odLoopAudio.isPlaying)
		{
			string audioID = "FireBlastODLoop";
			Transform originTrans = spawnTransform;
			odLoopAudio = SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		}
	}

	private void StopAudio()
	{
		if (odLoopAudio != null)
		{
			odLoopAudio.Stop();
			odLoopAudio = null;
			SoundManager.PlayAudioWithDistance("FireBlastODEnd", spawnTransform.position);
		}
	}
}
using System.Collections;
