	public IEnumerator ArcanaDisplayLoop()
	{
		string levelName = Application.loadedLevelName;
		int skillIndex = 0;
		Transform arcanaDisplayTrans = GameObject.Find("Museum").transform.Find("Areas/ArcanaExhibit/Display");
		Arcana arcana = Globals.ChaosInst<Arcana>(Arcana.Prefab, arcanaDisplayTrans, arcanaDisplayTrans.position + new Vector3(0f, 1.25f, 0f));
		arcana.light.enabled = false;
		arcana.bgRenderer.color = new Color(arcana.bgRenderer.color.r, arcana.bgRenderer.color.g, arcana.bgRenderer.color.b, 0.65f);
