			arcana.iconRenderer.sprite = IconManager.GetSkillIcon(skillIDs[skillIndex]);
			arcana.anim.Play("SpinToFront", -1, 0f);
			yield return null;
			while (!arcana.anim.AnimPlayed())
			{
				yield return null;
			}
			arcana.anim.Play("FlashFront", -1, 0f);
			yield return null;
			while (!arcana.anim.AnimPlayed())
			{
				yield return null;
			}
			yield return waitForHalf;
			arcana.anim.Play("SummonEntity", -1, 0f);
			yield return null;
			while (!arcana.anim.AnimPlayed())
			{
				yield return null;
			}
			yield return waitForThreeQts;
