			if ((crowdAudio == null || !crowdAudio.isPlaying) && !SoundManager.isPaused)
			{
				crowdAudio = SoundManager.PlayAudio("CrowdMurmur");
			}
		}
		else if (crowdAudio != null)
		{
			crowdAudio.Stop();
			crowdAudio = null;
		}
	}

	public IEnumerator StartAdventure()
	{
		playCrowdAudio = false;
		SoundManager.PlayBGM(string.Empty);
		GameController.PauseAllPlayers();
		sparkleEmitter.Stop();
		GameController.cameraController.disablePlayerTracking = true;
		CameraController cameraController = GameController.cameraController;
		Vector3? targetLoc = playerWinItemTrans.position;
		cameraController.OverrideAndMoveCameraToLocation(null, targetLoc, 1.5f, followPlayer: false, setLocks: true);
		yield return waitForHalf;
		auraEmitter.SetActive(value: true);
		float totalDelayTime = 1f;
		float curDelayTime = totalDelayTime;
		float ogIntensity = stageLight.intensity;
		while (curDelayTime > 0f)
		{
			curDelayTime -= Time.deltaTime;
			float lerpTime = 1f - curDelayTime / totalDelayTime;
			stageLight.intensity = Mathf.Lerp(ogIntensity, 0f, lerpTime);
			playerWinItemLight.intensity = Mathf.Lerp(0f, 1.5f, lerpTime);
			yield return null;
		}
		stageLight.intensity = 0f;
		yield return waitForHalf;
		EmitLightningFromEmblem();
		glassSpriteTop.sprite = glassSprites[0];
		yield return waitForHalf;
		EmitLightningFromEmblem();
		glassSpriteTop.sprite = glassSprites[1];
