		EmitLightningFromEmblem();
		yield return waitForQuarter;
		playerWinItemAnim.Play("Flash", -1, 0f);
		glassSpriteBot.enabled = false;
		CameraController.ShakeCamera(0.5f);
		yield return waitForQuarter;
