		glassSpriteTop.material.SetFloat("_FlashAmount", 1f);
		SoundManager.PlayAudio("ChaosLightningCrackle");
		EmitLightningFromEmblem();
		EmitLightningFromEmblem();
		EmitLightningFromEmblem();
		yield return waitForQuarter;
		glassSpriteTop.material.SetFloat("_FlashAmount", 0f);
		glassSpriteTop.sprite = glassSprites[2];
		glassSpriteTopBG.sprite = glassSprites[3];
