		PoolManager.GetPoolItem<ParticleEffect>("GlassBreakEffectLarge").Emit(8, playerWinItemSpriteTrans.position, pSysOverride);
		PoolManager.GetPoolItem<ParticleEffect>("GlassBreakEffect").Emit(15, playerWinItemTrans.position, pSysOverride);
		SoundManager.PlayAudio("Shatter");
		playerWinItemAnim.Play("Float", -1, 0f);
		auraEmitter.SetActive(value: false);
		CameraController cameraController2 = GameController.cameraController;
		targetLoc = playerWinItemTrans.position;
		cameraController2.OverrideAndMoveCameraToLocation(null, targetLoc, 0.1f);
		yield return waitForOne;
		playerWinItemAnim.Play("SpinUp", -1, 0f);
		SoundManager.PlayAudio("CrestSpinUp");
		yield return null;
		CameraController cameraController3 = GameController.cameraController;
		targetLoc = playerWinItemTrans.position + Vector3.up * 2f;
		cameraController3.OverrideAndMoveCameraToLocation(null, targetLoc, 2f, followPlayer: false, setLocks: true);
