		CameraController.ShakeCamera(0.5f);
		yield return new WaitForSeconds(0.2f);
		CameraController.ShakeCamera(0.75f);
		SoundManager.PlayAudio("LightBeamWindup");
		int beamLoops = 3;
		int beamCountMax = 3;
		bool initialBeams = true;
		float initAngle = 0f;
		while (beamLoops > 0)
		{
			if (!initialBeams)
			{
				beamCountMax = Random.Range(2, 3);
			}
			else
			{
				initialBeams = false;
			}
			initAngle = Random.Range(0f, 360f);
			for (int i = 0; i < beamCountMax; i++)
			{
				AnimEffect poolItem = PoolManager.GetPoolItem<AnimEffect>("LightBeam");
