				float num2 = num;
				poolItem.Play(playerWinItemTrans.position, animSpeed: Random.Range(0.5f, 1.25f), localEulerAngles: new Vector3(0f, 0f, Random.Range(num - 45f, num2 + 45f)), animName: string.Empty, normalizedTime: Random.Range(0f, 0.15f));
